import * as React from 'react'

import { cx } from '~/lib/cx'
import styles from './tabs.module.scss'

type Orientation = 'horizontal' | 'vertical'

interface TabsContextValue {
  value: string
  setValue: (next: string) => void
  baseId: string
  orientation: Orientation
}

const TabsContext = React.createContext<TabsContextValue | null>(null)

function useTabs(component: string): TabsContextValue {
  const context = React.useContext(TabsContext)
  if (!context) {
    throw new Error(`<${component}> must be rendered inside <Tabs>.`)
  }
  return context
}

export interface TabsProps extends React.HTMLAttributes<HTMLDivElement> {
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  orientation?: Orientation
}

export function Tabs({
  value: valueProp,
  defaultValue = '',
  onValueChange,
  orientation = 'horizontal',
  className,
  children,
  ...props
}: TabsProps) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue)
  const value = valueProp ?? uncontrolled
  const baseId = React.useId()

  const setValue = React.useCallback(
    (next: string) => {
      if (valueProp === undefined) setUncontrolled(next)
      onValueChange?.(next)
    },
    [valueProp, onValueChange],
  )

  const context = React.useMemo<TabsContextValue>(
    () => ({ value, setValue, baseId, orientation }),
    [value, setValue, baseId, orientation],
  )

  return (
    <TabsContext.Provider value={context}>
      <div
        className={cx(styles.root, className)}
        data-orientation={orientation}
        {...props}
      >
        {children}
      </div>
    </TabsContext.Provider>
  )
}

export function TabsList({
  className,
  onKeyDown,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  const { orientation } = useTabs('TabsList')

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event)
    if (event.defaultPrevented) return

    const forward =
      orientation === 'horizontal' ? 'ArrowRight' : 'ArrowDown'
    const backward =
      orientation === 'horizontal' ? 'ArrowLeft' : 'ArrowUp'
    const navigation = [forward, backward, 'Home', 'End']

    if (!navigation.includes(event.key)) return

    const tabs = Array.from(
      event.currentTarget.querySelectorAll<HTMLButtonElement>(
        '[role="tab"]:not([disabled])',
      ),
    )
    if (tabs.length === 0) return

    event.preventDefault()

    const current = tabs.indexOf(event.target as HTMLButtonElement)
    let next = current

    if (event.key === forward) next = (current + 1) % tabs.length
    if (event.key === backward) next = (current - 1 + tabs.length) % tabs.length
    if (event.key === 'Home') next = 0
    if (event.key === 'End') next = tabs.length - 1

    tabs[next]?.focus()
    tabs[next]?.click()
  }

  return (
    <div
      role="tablist"
      aria-orientation={orientation}
      className={cx(styles.list, orientation === 'vertical' && styles.vertical, className)}
      onKeyDown={handleKeyDown}
      {...props}
    >
      {children}
    </div>
  )
}

export interface TabsTriggerProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  value: string
}

export function TabsTrigger({
  value,
  className,
  children,
  ...props
}: TabsTriggerProps) {
  const tabs = useTabs('TabsTrigger')
  const selected = tabs.value === value

  return (
    <button
      {...props}
      type="button"
      role="tab"
      id={`${tabs.baseId}-tab-${value}`}
      aria-selected={selected}
      aria-controls={`${tabs.baseId}-panel-${value}`}
      tabIndex={selected ? 0 : -1}
      className={cx(styles.trigger, className)}
      onClick={(event) => {
        props.onClick?.(event)
        if (!event.defaultPrevented) tabs.setValue(value)
      }}
    >
      {children}
    </button>
  )
}

export interface TabsContentProps
  extends React.HTMLAttributes<HTMLDivElement> {
  value: string
}

export function TabsContent({
  value,
  className,
  children,
  ...props
}: TabsContentProps) {
  const tabs = useTabs('TabsContent')
  const selected = tabs.value === value

  return (
    <div
      role="tabpanel"
      id={`${tabs.baseId}-panel-${value}`}
      aria-labelledby={`${tabs.baseId}-tab-${value}`}
      tabIndex={0}
      hidden={!selected}
      className={cx(styles.content, className)}
      {...props}
    >
      {children}
    </div>
  )
}

@use 'styles' as vz;

.root {
  display: flex;
  flex-direction: column;
  gap: vz.space(4);
  width: 100%;
}

.list {
  display: inline-flex;
  align-items: center;
  gap: vz.space(1);
  padding: vz.space(1);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('lg');
  background: vz.color('muted');
  align-self: flex-start;
  max-width: 100%;
  overflow-x: auto;

  @include vz.scrollbar(6px);
}

.vertical {
  flex-direction: column;
  align-items: stretch;
  align-self: flex-start;
}

.trigger {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  gap: vz.space(2);
  height: vz.space(8);
  padding-inline: vz.space(3.5);
  border: 0;
  border-radius: vz.radius('md');
  background: transparent;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    color vz.duration('fast') vz.ease('out'),
    box-shadow vz.duration('fast') vz.ease('out');

  @include vz.hover {
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 2px, 0.6);

  @include vz.disabled {
    opacity: 0.45;
    pointer-events: none;
  }
}

.trigger[aria-selected='true'] {
  background: vz.color('card');
  color: vz.color('foreground');
  box-shadow: vz.elevation(1);
}

.vertical .trigger {
  justify-content: flex-start;
}

.content {
  outline: none;

  @include vz.focus-ring(2px, 2px, 0.6);
}

.content:not([hidden]) {
  animation: vz-tab-in 260ms vz.ease('out') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

.content[hidden] {
  display: none;
}

@keyframes vz-tab-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}
